// Lit le rapport acteur et les trois gabarits de prompt versionnés dans /prompts, puis assemble les prompts.
// Un seul item en sortie (le rapport tient dans num_ctx = 8192 tokens : ~800 mots) ; pour un rapport plus long,
// découper ici en morceaux et produire un item par morceau.
const fs = require('fs');
const rapport = fs.readFileSync('/data/rapport-acteur.txt', 'utf8');
const candidats = fs.readFileSync('/prompts/candidats-attack.txt', 'utf8');
const texte = rapport.slice(0, 24000);
// Nom de l'acteur : première ligne du rapport, avant « : » (SILEX-7 pour le rapport fil rouge), nettoyé pour servir de nom de fichier.
const acteur = (rapport.split('\n')[0].split(':')[0].trim() || 'acteur').toLowerCase().replace(/[^a-z0-9-]+/g, '-').replace(/^-+|-+$/g, '');
const lire = f => fs.readFileSync('/prompts/' + f, 'utf8');
const remplir = t => t.replace('{{TEXTE}}', texte).replace('{{CANDIDATS}}', candidats.trim());
return [{ json: {
  acteur,
  prompt_yara: remplir(lire('gen-yara.md')),
  prompt_sigma: remplir(lire('gen-sigma.md')),
  prompt_attack: remplir(lire('map-attack.md')),
  longueur_rapport: rapport.length
} }];

// Récupère les trois réponses d'Ollama (une branche par prompt), retire les éventuelles clôtures Markdown
// (```yara, ```yaml, ```json) que le modèle ajoute malgré la consigne, et écrit les règles dans /out/ia/.
// Le rapport est un seul item : on lit l'item 0 de chaque branche (itemMatching(0) si plusieurs morceaux).
const fs = require('fs');
const acteur = $('Lire le rapport').first().json.acteur;
const dir = '/out/ia/';
fs.mkdirSync(dir, { recursive: true });
function nettoyer(s) {
  s = String(s || '').trim();
  s = s.replace(/^```[a-zA-Z]*\s*\n/, '').replace(/\n```\s*$/, '');
  return s.trim() + '\n';
}
const yara = nettoyer($('Ollama YARA').first().json.response);
const sigma = nettoyer($('Ollama Sigma').first().json.response);
let attackRaw = nettoyer($('Ollama ATT&CK').first().json.response);
let attack;
try { attack = JSON.parse(attackRaw); } catch (e) { attack = { erreur: 'JSON invalide', brut: attackRaw }; }
// Garde-fou : ne conserver que les identifiants présents dans la liste fermée de candidats (défense contre l'invention).
const candidats = fs.readFileSync('/prompts/candidats-attack.txt', 'utf8').split('\n').map(l => l.split(' - ')[0].trim()).filter(Boolean);
if (Array.isArray(attack.techniques)) {
  attack.hors_liste = attack.techniques.filter(t => !candidats.includes(String(t.id || '').toUpperCase()));
  attack.techniques = attack.techniques.filter(t => candidats.includes(String(t.id || '').toUpperCase()));
}
const fYara = dir + acteur + '-ia.yar', fSigma = dir + acteur + '-ia.yml', fAttack = dir + 'attack-ia.json';
fs.writeFileSync(fYara, yara);
fs.writeFileSync(fSigma, sigma);
fs.writeFileSync(fAttack, JSON.stringify(attack, null, 2) + '\n');
const lat = n => Math.round(($(n).first().json.total_duration || 0) / 1e6);
return [{ json: {
  acteur, fichiers: [fYara, fSigma, fAttack],
  modele: $('Ollama YARA').first().json.model,
  latence_ms: { yara: lat('Ollama YARA'), sigma: lat('Ollama Sigma'), attack: lat('Ollama ATT&CK') },
  n_techniques: Array.isArray(attack.techniques) ? attack.techniques.length : 0,
  n_hors_liste: Array.isArray(attack.hors_liste) ? attack.hors_liste.length : 0,
  yara_apercu: yara.slice(0, 300), sigma_apercu: sigma.slice(0, 300)
} }];

// Journal des générations, pour le livrable comparatif-humain-ia.md (une ligne JSON par exécution).
// À faire ensuite à la main (TP 3, B2) : yara -r out/ia/<acteur>-ia.yar data/samples/ ; sigma-test.py out/ia/<acteur>-ia.yml …
const fs = require('fs');
for (const item of $input.all()) {
  fs.appendFileSync('/out/ia/generations.jsonl', JSON.stringify({ ts: new Date().toISOString(), ...item.json }) + '\n');
}
return $input.all();
